// gtmux native DeepSeek Harness plugin; generated by install-hooks --agent dsh.
// Uses Cordis lifecycle events directly, never the Codex/Claude hook bridges.
import { spawn } from 'node:child_process';
import {createHash, randomBytes} from 'node:crypto';
export const name = 'gtmux-dsh';

// Native account service only: no credential resolution, inference, or API-key guessing.
// Exported for synthetic account-switch and late-response tests.
export function observeAccountUsage(ctx, emit) {
  if (typeof ctx.inject !== 'function') return;
  ctx.inject(['deepseekAccount'], scope => {
    const account = scope.deepseekAccount;
    if (!account) return;
    const source_id = randomBytes(16).toString('hex');
    const controller = new AbortController();
    let generation = 1, running = false, pending = false, activeID, signedOut = false;
    const send = (status, extra = {}) => emit('Usage', {source_id, generation, status, ...(activeID ? {account_id: activeID} : {}), ...extra});
    const identity = async () => {
      const value = await account.getDeviceIdentity?.();
      if (typeof value?.userId !== 'string' || !value.userId || value.userId.length > 256) return;
      return createHash('sha256').update(`deepseek-account\0${value.userId}`).digest('hex');
    };
    const refresh = async () => {
      if (controller.signal.aborted || signedOut) return;
      if (running) {pending = true; return;}
      running = true;
      const revision = generation;
      let timeout, expired = false;
      try {
        if (typeof account.getBalance !== 'function') {send('unsupported'); return;}
        const id = await identity();
        if (controller.signal.aborted || revision !== generation) return;
        if (activeID && activeID !== id) send('signed-out');
        activeID = id;
        if (!id) {if (revision === generation) send('unverified-account'); return;}
        send('unavailable');
        timeout = setTimeout(() => {expired = true; if (!controller.signal.aborted && revision === generation) send('unavailable');}, 8000);
        timeout.unref?.();
        // The native service has no cancellation argument. A timed-out request
        // retains this single-flight slot until it settles; no retry pile-up.
        const result = await account.getBalance({version: __GTMUX_VERSION__, locale: 'en-US', timezoneOffsetSeconds: -new Date().getTimezoneOffset()*60});
        if (expired || controller.signal.aborted || revision !== generation) return;
        const settledID = await identity();
        if (expired || controller.signal.aborted || revision !== generation || id !== settledID) return;
        if (result?.status !== 'ready') {send(result === null ? 'signed-out' : 'unavailable'); return;}
        const wallets = [];
        for (const [kind, values] of [['recharge', result.value], ['bonus', result.bonusWallets]]) {
          if (!Array.isArray(values)) {send('unavailable'); return;}
          for (const wallet of values) {
            if (!['CNY', 'USD'].includes(wallet.currency) || typeof wallet.balance !== 'string' || !/^-?(?:0|[1-9][0-9]{0,19})(?:\.[0-9]{1,12})?$/.test(wallet.balance)) {send('unavailable'); return;}
            wallets.push({kind, currency: wallet.currency, amount: wallet.balance});
          }
        }
        if (!wallets.length || wallets.length > 8) {send('unavailable'); return;}
        send('ready', {account_id: id, wallets});
      } catch {
        if (!controller.signal.aborted && revision === generation) send('unavailable');
      } finally {
        clearTimeout(timeout); running = false;
        if (pending) {pending = false; queueMicrotask(refresh);}
      }
    };
    const changed = state => {
      if (controller.signal.aborted) return;
      generation++;
      signedOut = state?.status === 'signed-out';
      send(state?.status === 'signed-out' ? 'signed-out' : 'unavailable');
      if (state?.status === 'signed-out') activeID = undefined;
      else void refresh();
    };
    if (typeof account.watch === 'function') {
      void (async () => {try {for await (const state of account.watch(controller.signal)) changed(state);} catch {if (!controller.signal.aborted) {generation++; send('unavailable');}}})();
    } else {
      generation++;
      void refresh();
    }
    void refresh();
    const timer = setInterval(() => {void refresh();}, 5*60*1000);
    timer.unref?.();
    scope.on('dispose', () => {controller.abort(); clearInterval(timer);});
  });
}
export function observe(ctx, emit) {
  observeAccountUsage(ctx, emit);
  const turns = new WeakMap(), questions = new WeakMap();
  const root = session => session?.header?.version === 4 && session.header.origin !== 'subagent';
  const text = blocks => (Array.isArray(blocks) ? blocks : []).filter(b => b?.type === 'text' && typeof b.text === 'string').map(b => b.text).join('\n').slice(0, 65536);
  ctx.on('session/event', (session, event) => {
    if (!root(session)) return;
    const d = event.data || {};
    const payload = {session_id: session.id, cwd: session.header.cwd || '', turn_id: String(d.turn ?? '')};
    switch (event.type) {
      case 'user/message':
        if (event.surfaceOp && event.surfaceOp !== 'append') break;
        if (d.source?.kind === 'user' && d.role === 'user') emit('UserPromptSubmit', {...payload, prompt: text(d.content)});
        break;
      case 'turn/start': turns.set(session,payload.turn_id); questions.set(session,new Set()); emit('TurnStarted', payload); break;
      case 'turn/end': {
        questions.delete(session);
        const kind = d.reason?.kind;
        // A blocked/error/budget-limited turn did not successfully finish.
        const token = kind === 'completed' ? 'Stop' : ['aborted', 'interrupted', 'forked'].includes(kind) ? 'Interrupt' : 'StopFailure';
        emit(token, payload); break;
      }
      // Neither a tool invocation nor approval/asked proves a human is waiting:
      // DSH may resolve approvals through automatic policy or another plugin.
    }
  }, {global: true});
  // This is the native human-question seam. Observe and delegate the exact
  // request/result; never supply an answer or replace an approval policy.
  ctx.on('user-questions/request', async (request, next) => {
    const session = request.agent?.session;
    if (!root(session)) return next();
    const payload = {session_id: session.id, cwd: session.header.cwd || '', turn_id: turns.get(session) || ''};
    const pending = questions.get(session) || new Set(); questions.set(session,pending);
    const key = {};
    let shown = false;
    const timer = setTimeout(() => {
      if (questions.get(session) !== pending) return;
      shown = true; pending.add(key); if (pending.size === 1) emit('Question', payload);
    }, 250);
    timer.unref?.();
    try { return await next(); }
    finally {
      clearTimeout(timer);
      if (shown) {pending.delete(key); if (questions.get(session) === pending && pending.size === 0) emit('Resumed', payload);}
    }
  }, {global: true, prepend: true});
}
export function hookSink(ctx, extra = () => ({})) {
  const BIN = __GTMUX_BIN__;
  const queue = [];
  let child, disposed = false, timer;
  const drain = () => {
    if (disposed || child || !queue.length) return;
    const [token, payload] = queue.shift();
    try {
      // This child still has the native DSH parent. Only a reparented gtmux
      // worker uses --detached, which skips the pre-detach ancestry capture.
      child = spawn(BIN, ['hook', '--agent', 'dsh', token], {
        env: {...process.env, TMUX_PANE: ''}, stdio: ['pipe', 'ignore', 'ignore'],
      });
      const current = child;
      let finished = false;
      const done = () => { if (finished) return; finished = true; clearTimeout(timer); child = undefined; drain(); };
      child.on('error', done); child.on('close', done);
      child.stdin.on('error', () => {});
      child.stdin.end(JSON.stringify(payload));
      timer = setTimeout(() => { current.kill('SIGKILL'); }, 5000);
      timer.unref();
    } catch { child = undefined; queueMicrotask(drain); }
  };
  const send = (token, payload) => {
    // An unavailable CLI must never backpressure the agent or retain chat history.
    if (!disposed && queue.length < 64) { queue.push([token, {...payload, ...extra(payload)}]); drain(); }
  };
  ctx.on('dispose', () => { disposed = true; queue.length = 0; clearTimeout(timer); child?.kill('SIGKILL'); });
  return send;
}
export function apply(ctx) {
  // Terminal clients load their own admitted bridge and retain the same harness
  // identity. A Web overlay in that profile must not duplicate its observations.
  if (ctx.get?.('tuiPluginHost', false)) return;
  observe(ctx, hookSink(ctx));
}
